// Hindi for sages/narada.js — keys are HI.hash(<Telugu string>). Written by tools/hi_write.js.
HI.add({
 "12128182": "नारद बने स्त्री",
 "45842890": "नारद की वीणा का नाम महती है, जो भगवान ने उन्हें भेंट में दी थी।",
 "64529486": "नारद को वैसे ही सोचिए जैसे भारतीय कला उन्हें हमेशा दिखाती आई है: दुबले-पतले मुनि, सिर पर शिखा, गले में तुलसी की माला, एक हाथ में छोटे-छोटे मंजीरे और कंधे पर वीणा। आकाश में चलते हुए वे गाते रहते हैं — “नारायण, नारायण।” भागवत के पहले स्कंध में वे व्यास को बताते हैं कि यह वीणा उन्हें स्वयं भगवान ने दी थी, और वे घूमते हुए इसे बजाकर हरि की कथाएँ गाते हैं।",
 "68557311": "बहुत समय बाद गोकुल में यशोदा ने मक्खन चुराने पर नटखट बालक कृष्ण को लकड़ी की भारी ओखली से बाँध दिया। घुटनों के बल चलते हुए वे ओखली को खींचकर अर्जुन के दो ऊँचे पेड़ों के बीच ले गए। ओखली अटक गई — और बड़े ज़ोर की आवाज़ के साथ दोनों पेड़ गिर पड़े। उनमें से दो तेजस्वी पुरुष निकले, कुबेर के पुत्र, जिन्होंने बालक को प्रणाम किया और उनकी स्तुति गाई। नारद का श्राप उनके लिए वरदान बन गया था।",
 "88159172": "ध्रुव घर लौटे, पर पूरी तरह खुश नहीं थे। उन्होंने सोचा, “मैं उन भगवान के पास गया जो मोक्ष तक दे सकते हैं, और मैंने एक राज्य माँग लिया — जैसे कोई गरीब आदमी सम्राट को प्रसन्न करके मुट्ठी भर टूटे चावल माँग ले।” पिता ने उन्हें गले लगाया और राजगद्दी पर बिठाया। सुरुचि ने भी उन्हें प्रणाम किया। बाद में उनके सौतेले भाई उत्तम को शिकार करते समय एक यक्ष ने मार डाला, और दुःख में ध्रुव ने यक्षों से युद्ध छेड़कर बहुतों को मार डाला, जब तक कि उनके दादा मनु ने आकर प्यार से नहीं समझाया कि क्रोध उन्हें शोभा नहीं देता। ध्रुव रुक गए, कुबेर से संधि की, लंबे समय तक अच्छी तरह राज किया, और अंत में अपने तारे तक पहुँच गए।",
 "95078726": "भागवत पुराण, स्कंध 7, अध्याय 1 (शिशुपाल का अंत और युधिष्ठिर का प्रश्न), अध्याय 4–10 (प्रह्लाद का जीवन और नरसिंह), विशेषकर अध्याय 7 (नारद के आश्रम में कयाधू)। बम्मेर पोतन, आंध्र महाभागवतमु, स्कंध 7।",
 "90e2f0b0": "दासी का बेटा",
 "f8d75140": "हमारी कथा एक और महर्षि के उदास होने से शुरू होती है। {vyasa|व्यास} ने वेद को चार भागों में बाँटा था। उन्होंने महाभारत रचा था, इतना बड़ा काव्य कि उसमें लगभग सब कुछ समा जाता है। फिर भी सरस्वती नदी के किनारे अपने आश्रम में अकेले बैठे हुए उन्हें लगा कि कुछ कमी है। उन्होंने सोचा, “मैंने इतना सब किया, फिर भी मेरा मन भरा नहीं। क्यों?”",
 "a7c14929": "उसी समय आकाश से वीणा की आवाज़ आई, और साथ में हरि के नाम गाते हुए एक मुनि उतरे। वे नारद थे। व्यास ने उठकर उनका स्वागत किया। नारद ने मुस्कुराकर कहा: “आपने धर्म के बारे में लिखा, राजाओं और युद्धों के बारे में, कर्तव्य और धन के बारे में। पर आपने पूरे मन से, केवल उसी के लिए, भगवान की महिमा नहीं गाई। इसीलिए आपका मन खाली है। उनका गुणगान कीजिए, आपको शांति मिलेगी।”",
 "638bee0d": "फिर व्यास को यह दिखाने के लिए कि भगवान का नाम क्या कर सकता है, नारद ने उन्हें एक रहस्य बताया: अपने पिछले जन्म की कहानी। उन्होंने कहा, “आज आप मुझे ऐसे मुनि के रूप में देखते हैं जो सब लोकों में जहाँ चाहे घूमता है। पर पिछले कल्प में मैं एक दासी का बेटा था।”",
 "4af4fb30": "मुनियों की सेवा करने वाला बालक",
 "0106fff9": "उसकी माँ कुछ ब्राह्मणों के घर दासी का काम करती थी। एक साल बरसात के चार महीनों में घूमने वाले कुछ साधु वहाँ ठहरने आए, जैसे ऐसे मुनि तब करते हैं जब रास्तों में बाढ़ आ जाती है। छोटे बालक को उनकी देखभाल का काम मिला। वह उनके लिए पानी लाता, उनकी जगह साफ़ करता और चुपचाप उनके पास बैठा रहता। वह केवल पाँच साल का था, पर न शरारत करता था, न ज़्यादा बोलता था।",
 "d6d06322": "मुनियों को उससे लगाव हो गया। उनकी अनुमति से वह दिन में एक बार उनकी थालियों में बचा हुआ खाना खाता, और हर दिन उन्हें कृष्ण की कथाएँ गाते-सुनाते सुनता। भागवत कहता है कि धीरे-धीरे उसका मन धुलकर साफ़ हो गया, और उसके भीतर भगवान के लिए प्रेम जाग उठा। जब बरसात खत्म हुई और मुनि जाने लगे, तो उन्होंने बालक को अपना सबसे बड़ा उपहार दिया: उन्होंने उसे भगवान का ध्यान करना और भक्ति का गुप्त ज्ञान सिखाया।",
 "2803444b": "नारद कभी नहीं कहते कि वे चतुर थे या ऊँचे कुल में जन्मे थे। उनकी अपनी कहानी में, उनमें जो कुछ भी अच्छा है, वह कुछ महीनों की चुपचाप सेवा और सुनने से शुरू हुआ।",
 "f3d22515": "दुनिया में अकेला",
 "2980308e": "बालक की माँ उसे बहुत प्यार करती थी; वही उसका सब कुछ था। एक रात वह अँधेरे में गाय दुहने निकली, एक साँप पर उसका पैर पड़ गया और साँप ने उसे डस लिया। वह मर गई। छोटा बालक बिल्कुल अकेला रह गया। नारद ने व्यास को बताया, “मैं वैसे नहीं रोया जैसा आप सोचते होंगे। मुझे लगा कि भगवान, जो अपने प्रेमियों का भला चाहते हैं, उन्होंने मुझे बाँधने वाली आख़िरी रस्सी काट दी है। मैं उत्तर की ओर चल पड़ा।”",
 "1cd964da": "वह कस्बों और गाँवों से होकर, नदियों और पहाड़ों को पार करते हुए एक घने जंगल में पहुँचा। थका-प्यासा, उसने एक झरने का पानी पिया, एक पीपल के पेड़ के नीचे बैठ गया और वही किया जो मुनियों ने सिखाया था: आँखें बंद करके अपने हृदय में भगवान का ध्यान किया। और तब — एक पल के लिए — उसने उन्हें देखा। उसकी आँखों से आँसू बहने लगे; शरीर का हर रोम खड़ा हो गया; वह आनंद में डूब गया। फिर वह दर्शन चला गया।",
 "5e765d22": "उसने बार-बार कोशिश की, पर फिर उन्हें देख न सका। तब एक कोमल आवाज़ आई: “इस जन्म में तुम मुझे फिर नहीं देखोगे। जिनका मन अभी पूरी तरह शुद्ध नहीं हुआ, वे मुझे नहीं देख सकते। मैंने एक बार केवल इसलिए दर्शन दिए कि तुम्हारी लालसा बढ़े। तुमने मुनियों की सेवा की, इसलिए अब तुम्हारा मन मुझमें लग गया है, और यह मुझे कभी नहीं छोड़ेगा। जब यह शरीर छूटेगा, तब तुम मेरे अपने पार्षदों में से एक बनोगे।”",
 "074c6fcb": "ब्रह्मा से फिर जन्म",
 "8a619504": "तो वह बालक बिना लाज और बिना अभिमान के, भगवान के नाम गाते हुए और प्रतीक्षा करते हुए धरती पर घूमता रहा। समय आने पर उसका शरीर पके फल की तरह गिर गया। उस कल्प के अंत में, जब सारी सृष्टि लय हो गई और भगवान जल पर सो गए, तब वह भी बाकी सब के साथ {brahma|ब्रह्मा} में समा गया। हज़ार युगों के बाद जब ब्रह्मा फिर से सृष्टि करने के लिए जागे, तो वह मरीचि और दूसरे महर्षियों के साथ ब्रह्मा के पुत्र के रूप में फिर जन्मा। वही पुत्र नारद हैं।",
 "d076c073": "फिर नारद ने व्यास को उससे भी पहले के जन्मों के बारे में एक बात और बताई। भागवत के सातवें स्कंध में युधिष्ठिर से बात करते हुए वे कहते हैं कि उससे भी पहले के एक महाकल्प में वे उपबर्हण नाम के एक सुंदर गंधर्व थे। एक बार उन्हें प्रजापतियों के यज्ञ में गाने के लिए बुलाया गया। वे स्त्रियों से घिरे हुए आए, और भगवान के गीतों की जगह भोग-विलास के गीत गाने लगे। प्रजापतियों ने उन्हें सबसे नीचे के सेवकों में जन्म लेने का श्राप दिया — और इसी तरह वे दासी के बेटे बने।",
 "c70b7032": "व्यास ने सुना, और समझ गए। नारद अपनी वीणा लेकर गाते हुए आगे चल दिए। और व्यास सरस्वती के किनारे बैठकर श्रीमद्भागवत रचने लगे — भगवान की महिमा का ग्रंथ, जो बाद में उन्होंने अपने पुत्र शुक को पढ़ाया।",
 "e1b2f5d6": "भागवत पुराण, स्कंध 1, अध्याय 4–6 (व्यास की उदासी और नारद का पिछला जन्म); स्कंध 7, अध्याय 15 (गंधर्व उपबर्हण)।",
 "239fd91c": "नारद उदास {vyasa|व्यास} के पास आए और उनसे भगवान की महिमा गाने को कहा — और इस तरह भागवत का जन्म हुआ।",
 "586fe926": "पिछले जन्म में नारद एक दासी के बेटे थे, जिन्होंने घूमने वाले मुनियों की सेवा की।",
 "c719f504": "उस जन्म में उन्होंने भगवान को केवल एक बार देखा, और उसी एक झलक से उनका बाकी जीवन भर गया।",
 "5f5a6bee": "व्यास ने बड़े-बड़े काम किए थे, फिर भी उन्हें खालीपन लगता था। आपको क्या लगता है, जिस मन को बड़ी उपलब्धियाँ नहीं भर पातीं, उसे क्या भरता है?",
 "48996a20": "ब्रह्मा से जन्म — और दक्ष का श्राप",
 "2107c7fe": "पुराण नारद के {brahma|ब्रह्मा} से जन्म की बात एक से ज़्यादा तरह से बताते हैं। जैसा हमने देखा, भागवत का पहला स्कंध कहता है कि वे दूसरे मुनियों के साथ ब्रह्मा की श्वास से उत्पन्न हुए। तीसरा स्कंध कहता है कि ब्रह्मा का हर मानस पुत्र उनके अलग-अलग अंग से निकला — दक्ष अँगूठे से, वसिष्ठ श्वास से, भृगु त्वचा से — और नारद उनकी गोद से, उस जगह से जहाँ पिता अपने प्यारे बच्चे को रखता है।",
 "85e67056": "ब्रह्मा के दूसरे पुत्रों ने विवाह किया और संसार को संतानों से भर दिया। नारद ने ऐसा नहीं किया। ब्रह्मवैवर्त पुराण बताता है कि जब ब्रह्मा ने उनसे विवाह करके सृष्टि में हाथ बँटाने को कहा, तो नारद ने मना कर दिया: वे केवल भगवान का ध्यान करना चाहते थे। अपनी बात न माने जाने पर क्रोधित होकर ब्रह्मा ने उन्हें श्राप दिया कि वे कामना में पड़ें और गंधर्व बनकर जन्म लें — और इस तरह यह पुराण उनके इनकार को उपबर्हण वाले जन्म से जोड़ता है, जिसके बारे में हमने पहले अध्याय में सुना था।",
 "b629a04f": "नारद को देवर्षि कहा जाता है — देवताओं के बीच ऋषि। वे जब चाहें स्वर्ग, पृथ्वी और पाताल जा सकते हैं, इसलिए वे हर जगह खबरें पहुँचाते हैं।",
 "e9abee4a": "दक्ष के दस हज़ार पुत्र",
 "a7d06a74": "नारद के भाई {daksha|दक्ष} वह प्रजापति थे जिनका काम संसार को जीवों से भरना था। भागवत का छठा स्कंध बताता है कि उनके दस हज़ार पुत्र थे, जिन्हें {haryashvas|हर्यश्व} कहा जाता था। उन्होंने उन्हें पश्चिम में एक पवित्र सरोवर पर भेजा, जहाँ सिंधु नदी समुद्र से मिलती है, ताकि वे तपस्या करके बहुत-सी संतान पैदा करने की शक्ति पा सकें।",
 "2ace65cc": "नारद वहाँ उनके पास आए और उनसे पहेलियाँ पूछीं। “जब तुमने पृथ्वी का अंत ही नहीं देखा, तो सृष्टि कैसे करोगे? वह कौन-सा देश है जहाँ केवल एक ही पुरुष है? वह कौन-सा बिल है जिससे कोई बाहर नहीं निकलता? अनेक रूपों वाली स्त्री कौन है? वह कौन-सी नदी है जो दोनों ओर बहती है? पच्चीस चीज़ों से बना घर कौन-सा है?” युवकों ने खूब सोचा। उन्होंने समझा कि वह एक पुरुष आत्मा है; अनेक रूपों वाली स्त्री चंचल मन है; पच्चीस का घर तत्वों से बना शरीर है। उन्होंने कहा, “जब हमने अपने ही शरीर को अभी तक नहीं समझा, तो और शरीर क्यों बनाएँ?” वे ज्ञान के मार्ग पर निकल पड़े और कभी नहीं लौटे।",
 "54b46511": "दक्ष अपने खोए हुए पुत्रों के लिए दुखी हुए। फिर उन्होंने एक हज़ार और पुत्रों को जन्म दिया, शबलाश्वों को, और उन्हें उसी सरोवर पर भेजा। नारद फिर आए, और उन्होंने भी संसार छोड़ दिया।",
 "6707d30e": "“तुम्हारा कभी कोई घर नहीं होगा”",
 "ae9fcd21": "अब दक्ष आग-बबूला हो गए। वे नारद से मिले और उन पर चिल्लाए: “तुम साधु का वेश पहनते हो, पर तुम साधु नहीं हो! मेरे पुत्रों ने अभी देवताओं, ऋषियों और पितरों का ऋण भी नहीं चुकाया था, और तुमने उन्हें संसार से मोड़ दिया। तुमने एक पिता का दिल दो बार तोड़ा। तुमने मेरे पुत्रों को भटकने वाला बना दिया, इसलिए तुम भी सदा लोकों में भटकते रहो, और कहीं ठहरने की जगह न पाओ!”",
 "d59d0847": "नारद भी पलटकर श्राप दे सकते थे। उन्होंने नहीं दिया। भागवत कहता है कि उन्होंने बस इतना कहा, “ऐसा ही हो,” और श्राप स्वीकार कर लिया — क्योंकि सच्चा साधु अपने साथ किया गया व्यवहार सह लेता है, भले ही उसमें जवाब देने की शक्ति हो। तब से नारद का न कोई घर है, न आश्रम। वे हमेशा चलते रहते हैं, स्वर्ग से पृथ्वी, महल से जंगल, गाते हुए।",
 "6e2d868c": "क्या नारद का दक्ष के पुत्रों के साथ ऐसा करना ठीक था? पुराण हमें दोनों पक्ष महसूस करने देते हैं। दक्ष का दुःख सच्चा है, और उनके पुत्रों ने उन्हें कभी पोते-पोतियाँ नहीं दीं। पर भागवत दक्ष को एक घमंडी व्यक्ति के रूप में भी दिखाता है, जिसने बाद में अपने बड़े यज्ञ में स्वयं शिव का अपमान किया। कहानी इस पर सोचने का काम हम पर छोड़ देती है।",
 "66705f0f": "दक्ष का यज्ञ — भृगु की कथा में",
 "305a4a5b": "महाभारत (आदि पर्व) और विष्णु पुराण भी बताते हैं कि नारद ने दक्ष के पुत्रों को सृष्टि के काम से कैसे मोड़ दिया। बाद में मिले श्राप के बारे में वे अलग-अलग बातें कहते हैं, पर हर कथा इस पर सहमत है कि दक्ष ने उन्हें कभी माफ़ नहीं किया।",
 "a0bceab3": "भागवत पुराण 1.6 (ब्रह्मा की श्वास से जन्म) और 3.12 (ब्रह्मा की गोद से जन्म); 6.5 (हर्यश्व, शबलाश्व और दक्ष का श्राप)। ब्रह्मवैवर्त पुराण, ब्रह्म खंड (ब्रह्मा का श्राप)। महाभारत, आदि पर्व; विष्णु पुराण 1.15।",
 "448afc2a": "नारद {brahma|ब्रह्मा} के मानस पुत्र हैं, जिन्हें देवर्षि कहा जाता है।",
 "fc19fcd6": "उन्होंने {daksha|दक्ष} के हज़ारों पुत्रों को संतान पैदा करने से हटाकर आत्मज्ञान की खोज की ओर मोड़ दिया।",
 "e8e28b71": "दक्ष ने उन्हें सदा भटकने का श्राप दिया — और नारद ने पलटकर श्राप दिए बिना उसे स्वीकार कर लिया।",
 "6875149b": "दक्ष ने अपने पुत्र खो दिए; पुत्रों ने ज्ञान पा लिया। आप किसके पक्ष को ज़्यादा महसूस करते हैं — और क्या दोनों सही हो सकते हैं?",
 "11caeb92": "महती वीणा और श्वेतद्वीप",
 "9a0f1577": "उनकी वीणा का एक नाम है: महती, यानी “महान”। कवि माघ अपने शिशुपालवध काव्य की शुरुआत ही इस दृश्य से करते हैं कि नारद आकाश से द्वारका में {krishna|श्रीकृष्ण} के पास उतर रहे हैं। कृष्ण देखते हैं कि मुनि चलती हुई ज्वाला की तरह चमक रहे हैं, और जब हवा तारों को छूती है तो महती अपने आप स्वर छेड़ने लगती है।",
 "21175a94": "संगीत के कई पुराने ग्रंथ नारद के नाम से जुड़े हैं, जैसे नारदीय शिक्षा, जो बताती है कि सामवेद कैसे गाया जाता है। भारत के संगीतकार लंबे समय से उन्हें संगीत के संरक्षक के रूप में मानते आए हैं।",
 "8423a8b6": "नारायण किसकी पूजा करते हैं?",
 "fed9a982": "महाभारत के शांति पर्व में नारायणीय नाम का एक लंबा भाग है, और नारद उसके केंद्र में हैं। एक बार वे हिमालय में बदरी गए, जहाँ जुड़वाँ ऋषि नर और नारायण तपस्या कर रहे थे। उन्होंने देखा कि नारायण पूजा कर रहे हैं। नारद हैरान हुए। उन्होंने कहा, “आप तो सबके स्वामी हैं। आप किसकी पूजा कर सकते हैं?”",
 "2c14a142": "नारायण ने उत्तर दिया: “मैं अपने ही परम आत्मा की पूजा करता हूँ, जो सबका स्रोत है।” नारद उस परम रूप को देखने के लिए तरस गए, और नारायण ने उन्हें श्वेतद्वीप भेजा, जो क्षीरसागर के पार दूर उत्तर में है। वहाँ नारद को चंद्रमा जैसे चमकते प्राणी मिले, जो भगवान से प्रेम करने और उनकी पूजा करने के सिवा कुछ नहीं करते थे। वे एक पैर पर खड़े होकर, हाथ उठाकर, बहुत देर तक स्तुति गाते रहे — और आख़िर भगवान ने उन्हें अपना विराट रूप दिखाया, अनगिनत आँखों और मुखों वाला, सारे लोकों को धारण किए हुए।",
 "b399df81": "भगवान ने उनसे कहा: “बहुत कम लोग मुझे इस रूप में देख पाते हैं। तुमने मुझे इसलिए देखा क्योंकि तुम केवल मुझसे प्रेम करते हो।” और उन्होंने नारद को अनन्य भक्ति का मार्ग सिखाया, और वे रूप दिखाए जिनमें वे आने वाले युगों में धरती पर अवतार लेंगे — वराह, नरसिंह, वामन, राम और कृष्ण।",
 "672e1f7d": "तीनों लोकों के संदेशवाहक",
 "bbed3f5f": "इस तरह नारद पुराणों के सबसे बड़े संदेशवाहक बन जाते हैं। वे स्वर्ग से पृथ्वी तक, और पृथ्वी से पाताल तक खबरें ले जाते हैं। वे राजाओं को बताते हैं कि देवता क्या योजना बना रहे हैं; देवताओं को बताते हैं कि राजा क्या कर रहे हैं; वे चेताते हैं, सलाह देते हैं, और कभी-कभी झगड़ा भी करवा देते हैं। तेलुगु घरों में जब कोई इस घर की बात उस घर तक पहुँचाता है, तो लोग हँसकर कहते हैं, “लो, नारद आ गए!”",
 "18181b21": "पर पुरानी कथाएँ इस बारे में सावधान हैं। नारद के झगड़े लगभग हमेशा भलाई में खत्म होते हैं: कोई राक्षस मारा जाता है, कोई भक्त बचता है, कोई घमंडी नम्र होता है, कोई छिपा सच सामने आता है। लोग उन्हें कलहप्रिय, यानी “झगड़ों के शौकीन”, कहते थे, पर यह भी कहते थे कि नारद का शुरू किया झगड़ा छिपा हुआ वरदान होता है। जैसा अगले अध्याय दिखाएँगे, हमारी कई सबसे बड़ी कथाओं की शुरुआत में वही होते हैं।",
 "d896976c": "भागवत पुराण 1.6 (भगवान की दी हुई वीणा)। माघ, शिशुपालवध, सर्ग 1 (नारद का द्वारका में उतरना; महती)। महाभारत, शांति पर्व, नारायणीय भाग (बदरी, श्वेतद्वीप और विराट रूप)।",
 "8ee17e51": "नारायणीय में वे श्वेतद्वीप जाते हैं और भगवान का विराट रूप देखते हैं।",
 "b2408fe7": "उनके झगड़े मुसीबत जैसे लगते हैं, पर लगभग हमेशा भलाई में खत्म होते हैं।",
 "e1a03bfe": "नारद सब लोकों के बीच खबरें ले जाते हैं। खबर पहुँचाना कब मददगार होता है, और कब वह नुकसान करने वाली चुगली बन जाता है?",
 "3b4f216d": "वाल्मीकि का प्रश्न — राम की कथा में नारद",
 "f2a12dbd": "रामायण की शुरुआत ही नारद से होती है। बालकांड के बिल्कुल पहले सर्ग में तपस्या और वेद से प्रेम करने वाले महर्षि {valmiki|वाल्मीकि} ने नारद से पूछा: “क्या आज संसार में कोई ऐसा है जो सचमुच गुणवान हो — बलवान, कृतज्ञ, सत्यवादी, अपने व्रत में दृढ़, सब प्राणियों पर दया करने वाला, विद्वान, सुंदर, इंद्रियों को वश में रखने वाला, ईर्ष्या से रहित, और इतना वीर कि युद्ध में उसके क्रोध से देवता भी डरें?”",
 "0e530066": "नारद प्रसन्न हो गए। उन्होंने कहा, “ऐसा व्यक्ति बहुत दुर्लभ है, पर एक है। उसका जन्म इक्ष्वाकु वंश में हुआ है, और लोग उसे {rama|राम} के नाम से जानते हैं।” और लगभग सौ श्लोकों में उन्होंने राम की पूरी कथा सुना दी, जन्म से लेकर अयोध्या में उनके राज्य तक। उस छोटे-से वर्णन ने बीज बो दिया। कुछ ही समय बाद वाल्मीकि ने एक शिकारी को क्रौंच पक्षी को मारते देखा, उनके दुःख से एक श्लोक फूट पड़ा, और ब्रह्मा ने आकर उनसे कहा: उसी छंद में राम की कथा गाओ। यानी, नारद का उत्तर न होता तो रामायण भी न होती।",
 "712df525": "रामायण कैसे शुरू हुई — नारद और वाल्मीकि",
 "9cbd5ed7": "डाकू और राम-नाम — बाद की एक कथा",
 "8f3831f3": "वाल्मीकि की अपनी रामायण में वाल्मीकि के डाकू होने की कोई बात नहीं है। यह कहानी बाद के ग्रंथों से आती है। अध्यात्म रामायण में वाल्मीकि राम को बताते हैं कि वे कभी राहगीरों को लूटने वाले डाकू थे, और सात ऋषियों के एक समूह ने उन्हें राम का नाम जपना सिखाया — वे उसे केवल उल्टा बोल पाते थे, “मरा, मरा” — यहाँ तक कि उनके ऊपर दीमक की बाँबी बन गई।",
 "bcb2b9a2": "तेलुगु घरों में बहुत प्यार से सुनाई जाने वाली लोक-कथाएँ यह शिक्षा नारद को देती हैं। उनमें डाकू रत्नाकर जंगल के रास्ते पर नारद को रोकता है। नारद उससे पूछते हैं, “क्या तुम्हारा परिवार तुम्हारी लूट के पाप में हिस्सा लेगा?” डाकू पूछने घर जाता है; उसका परिवार कहता है, “हम तुम्हारी कमाई में हिस्सेदार हैं, तुम्हारे पापों में नहीं।” हिल जाने पर वह नारद के पास लौटता है, और नारद उसे राम का नाम देते हैं। यह रूप न वाल्मीकि में है, न उन पुराणों में जिनका हमने नाम लिया है; यह बाद की लोक-कथा है, और वाल्मीकि का जीवन हम उनके अपने अध्यायों में विस्तार से सुनाएँगे।",
 "d3c420dd": "नारद और रावण",
 "7ea8b405": "उत्तरकांड बताता है कि युद्ध से बहुत पहले, जब राक्षसराज रावण लोकों को जीत रहा था, तब नारद उससे कैसे मिले। नारद ने उसे एक बादल पर रोका और हँसकर कहा: “इन बेचारे मनुष्यों को क्यों सताते हो? ये तो पहले ही मर रहे हैं — बुढ़ापे से, बीमारी से, सौ तरह के दुखों से। जो पहले ही मारा जा रहा है उसे मारने में कोई बड़ाई नहीं। अगर सच्ची लड़ाई चाहिए, तो जाओ और स्वयं मृत्यु के देवता यम को जीतो।”",
 "9c9723d0": "तारीफ़ से फूला रावण यम की नगरी की ओर उड़ चला, और नारद देखने के लिए जल्दी से आगे पहुँच गए। भयंकर युद्ध हुआ। यम ने अपना कालदंड उठाया — और तभी {brahma|ब्रह्मा} प्रकट हुए और उन्हें रोक दिया, क्योंकि उन्होंने रावण को वचन दिया था कि कोई देवता उसे नहीं मार सकेगा। यम अदृश्य हो गए, और रावण ने अपनी जीत का दावा किया। नारद की शरारत ने कम से कम कुछ समय के लिए धरती के मनुष्यों को बचा लिया।",
 "256fb470": "एक कठिन प्रसंग — शंबूक",
 "c9646eca": "नारद उत्तरकांड की सबसे कठिन कथाओं में से एक में भी आते हैं। जब राम अयोध्या में राज कर रहे थे, एक ब्राह्मण अपने छोटे बेटे का शव लेकर रोता हुआ आया, और पुकारने लगा कि राजा के राज्य में किसी अधर्म के कारण यह असमय मृत्यु हुई है। दरबार में बैठे नारद ने अपने समय की भाषा में इसे समझाया: पहले के युगों में केवल कुछ वर्गों के लोग तपस्या करते थे, और अब राम के राज्य में एक शूद्र तपस्या कर रहा था, जो उस युग की व्यवस्था के विरुद्ध था।",
 "15f3d10f": "राम ने खोज की, और {shambuka|शंबूक} नाम के तपस्वी को उल्टा लटककर तपस्या करते पाया। उन्होंने पूछा कि वह कौन है, और जब शंबूक ने सच-सच उत्तर दिया, तो राम ने तलवार से उसे मार डाला। ब्राह्मण का बेटा फिर जी उठा। हम यह सीधे-सीधे इसलिए बता रहे हैं क्योंकि यह ग्रंथ में है। सदियों से बहुत-से पाठक इससे बेचैन होते आए हैं; कवि भवभूति अपने नाटक उत्तररामचरित में दिखाते हैं कि राम दुखी मन से वार करते हैं, और शंबूक एक चमकते दिव्य रूप में उठ खड़ा होता है। आपको भी बेचैनी हो सकती है — और इस पर सोचना सार्थक है।",
 "d30c8135": "अगस्त्य और राम — शंबूक के बाद",
 "6d8a65fd": "वाल्मीकि रामायण, बालकांड, सर्ग 1–2 (नारद का उत्तर; क्रौंच)। उत्तरकांड (नारद रावण को यम से लड़ने भेजते हैं; शंबूक प्रसंग)। अध्यात्म रामायण, अयोध्याकांड (वाल्मीकि का डाकू वाला अतीत)। भवभूति, उत्तररामचरित, अंक 2। रत्नाकर–नारद वाला रूप बाद की लोकप्रिय कथा है।",
 "ead7987b": "{valmiki|वाल्मीकि} का नारद से पूछा गया प्रश्न — “सचमुच गुणवान कौन है?” — रामायण की शुरुआत बना।",
 "f811a108": "डाकू और राम-नाम की कहानी बाद की कथा है; लोकप्रिय रूपों में नारद गुरु हैं।",
 "8b6b69e7": "नारद ने {ravana|रावण} को यम से लड़ने भेजा, और शंबूक के कठिन प्रसंग में भी बोले।",
 "23487b20": "वाल्मीकि ने पूछा, “क्या कोई सचमुच गुणवान है?” अगर आप अपने जान-पहचान वालों के बारे में यही पूछें, तो किसका नाम लेंगे, और क्यों?",
 "e2e1ad08": "पाँच साल के ध्रुव",
 "f3c229e3": "मनु के पुत्र राजा {uttanapada|उत्तानपाद} की दो रानियाँ थीं। वे छोटी रानी {suruchi|सुरुचि} और उसके बेटे उत्तम से बहुत प्यार करते थे। बड़ी रानी {suniti|सुनीति} और उसके बेटे {dhruva|ध्रुव} पर वे ज़्यादा ध्यान नहीं देते थे। एक दिन पाँच साल के नन्हे ध्रुव ने अपने सौतेले भाई को पिता की गोद में बैठे देखा और खुद भी ऊपर चढ़ना चाहा। राजा ने उसे गोद में नहीं उठाया।",
 "abaf8993": "पास में घमंड से खड़ी सुरुचि बोली: “तुम राजा के बेटे हो सकते हो, पर तुम मेरी कोख से नहीं जन्मे, इसलिए उस गोद पर या उस सिंहासन पर तुम्हारा कोई हक़ नहीं। अगर इतनी ही चाह है, तो जाओ, विष्णु की तपस्या करो, और फिर मेरी कोख से जन्म लो!” राजा कुछ नहीं बोले। डंडे से चोट खाए साँप की तरह ज़ोर-ज़ोर से साँस लेते हुए ध्रुव रोते हुए अपनी माँ के पास भागा।",
 "a1b768d9": "सुनीति ने उसे गले लगाया और खुद भी रो पड़ीं। पर उन्होंने उसे नफ़रत करना नहीं सिखाया। उन्होंने कहा, “बेटा, किसी का बुरा मत चाहना। उसने जो कहा वह एक तरह से सच है: जिसकी तुम्हें चाह है, वह केवल भगवान ही दे सकते हैं। पूरे मन से कमलनयन भगवान की आराधना करो।” ध्रुव ने आँसू पोंछे, और उसी दिन नगर छोड़कर चल पड़ा।",
 "6563c7e0": "नारद बालक की परीक्षा लेते हैं",
 "6bb2a33f": "रास्ते में नारद उससे मिले। उन्होंने बालक के सिर पर हाथ रखा और उसकी परीक्षा लेने के लिए उसे लौटाने की कोशिश की। उन्होंने कहा, “तुम तो अभी बच्चे हो। कुछ कड़वी बातों का बच्चे को क्या बुरा मानना? मान और अपमान हमें अपने ही पिछले कर्मों से मिलते हैं। और भगवान तक पहुँचना बहुत कठिन है — बड़े-बड़े योगी कई जन्मों तक कोशिश करके भी हार जाते हैं। घर जाओ। जब बड़े हो जाओ, तब तपस्या की सोचना।”",
 "a9235f9f": "ध्रुव ने हाथ जोड़कर उत्तर दिया: “महाराज, मैं जानता हूँ कि मैं छोटा हूँ और मेरा स्वभाव क्षत्रिय का है, स्वाभिमानी और न झुकने वाला। वे बातें मेरे दिल में चुभ गई हैं और निकलती नहीं। मुझे वह स्थान चाहिए जो मेरे पुरखों में से किसी को भी मिले स्थान से ऊँचा हो। कृपा करके — बस मुझे रास्ता बता दीजिए।” नारद का मन भर आया। उन्होंने देखा कि बालक का संकल्प सच्चा है।",
 "f634e8a9": "तो उन्होंने उसे सिखाया। “यमुना के किनारे मधुवन जाओ, जहाँ भगवान सदा पास रहते हैं। दिन में तीन बार स्नान करो। स्थिर बैठो, साँस को वश में करो, और अपने हृदय में भगवान का चित्र बनाओ — उनका कोमल मुख, उनकी मुस्कान, उनकी चार भुजाएँ, उनका पीला वस्त्र। और यह मंत्र जपो।” और उन्होंने ध्रुव को बारह अक्षरों का मंत्र दिया: ॐ नमो भगवते वासुदेवाय।",
 "4fc15e96": "नारद यहीं नहीं रुके। वे सीधे महल गए और राजा को पछतावे से भरा पाया। उन्होंने उत्तानपाद से कहा, “दुखी मत होइए। भगवान आपके बेटे की रक्षा कर रहे हैं। जल्द ही वह वह करेगा जो बड़े-बड़े राजा भी नहीं कर पाते, और उसकी कीर्ति सारे संसार में फैल जाएगी।”",
 "269729c0": "वह तपस्या जिसने लोकों को हिला दिया",
 "6c957ba4": "मधुवन में ध्रुव ने तपस्या शुरू की। पहले महीने वह हर तीसरे दिन फल खाता। दूसरे महीने हर छठे दिन सूखे पत्ते। तीसरे महीने हर नौवें दिन केवल पानी। चौथे महीने हर बारहवें दिन केवल हवा। पाँचवें महीने वह एक पैर पर खंभे की तरह स्थिर खड़ा हो गया, साँस रोककर, पूरा मन भगवान में लगाए। भगवान सब प्राणियों को धारण करते हैं, और भगवान ध्रुव के हृदय में धारण किए हुए थे, इसलिए भागवत कहता है कि जब बालक ने साँस रोकी, तो सारे संसार की साँस घुटने लगी। देवता घबराकर विष्णु के पास दौड़े।",
 "b38ea7dd": "{vishnu|विष्णु} गरुड़ पर बैठकर मधुवन आए। ध्रुव ने भीतर जो रूप बसाया था, वह अचानक गायब हो गया — और उसने आँखें खोलीं तो वही भगवान सामने खड़े थे। वह उनके चरणों में गिर पड़ा, पर उसे नहीं पता था कि उनकी स्तुति कैसे करे; वह तो बस एक बच्चा था। भगवान ने अपने शंख से धीरे से उसके गाल को छुआ, और उस स्पर्श से शब्द उमड़ पड़े, और ध्रुव ने एक सुंदर स्तुति गाई।",
 "71c9db51": "भगवान ने कहा: “मैं जानता हूँ तुम क्या चाहते थे। तुम कई हज़ार वर्षों तक अपने पिता के राज्य पर राज करोगे। और उसके बाद मैं तुम्हें वह स्थान देता हूँ जो आज तक किसी को नहीं मिला — आकाश का वह अटल बिंदु जिसके चारों ओर सारे तारे और ग्रह घूमते हैं, और जो लोकों के प्रलय में भी बना रहता है।” वह स्थान ध्रुवलोक है, और वह तारा ध्रुव तारा है, जिसे हम आज भी ध्रुव नक्षत्र कहते हैं।",
 "50a1f912": "ध्रुव का आगे का जीवन",
 "0558f596": "विष्णु पुराण ध्रुव की तपस्या थोड़ा अलग ढंग से बताता है। वहाँ बालक जंगल में नारद से नहीं, बल्कि सप्तर्षियों — मरीचि, अत्रि और बाकी — से मिलता है, और वे उसे आराधना करना सिखाते हैं। दोनों ग्रंथ कहानी के मूल पर सहमत हैं: एक आहत बच्चा जिसने बदले की जगह भक्ति चुनी, और किसी भी राजा से ऊँचा उठा दिया गया।",
 "c1b5de43": "भागवत पुराण, स्कंध 4, अध्याय 8–12 (ध्रुव का अपमान, नारद की शिक्षा, तपस्या, दर्शन, यक्षों से युद्ध और ऊपर के लोक में जाना)। विष्णु पुराण, स्कंध 1, अध्याय 11–12 (ध्रुव और सप्तर्षि)।",
 "d95ca54d": "सौतेली माँ की बातों से आहत होकर {dhruva|ध्रुव} पाँच साल की उम्र में भगवान को खोजने घर से निकल पड़े।",
 "a3bc2c7a": "नारद ने उनकी परीक्षा ली, फिर उन्हें मंत्र दिया: “ॐ नमो भगवते वासुदेवाय”।",
 "37ce082d": "विष्णु ने उन्हें ध्रुव तारा बनाया, आकाश का अटल बिंदु।",
 "bb0b121e": "सुनीति अपने बेटे को सुरुचि से नफ़रत करना सिखा सकती थीं। इसके बजाय उन्होंने उसे भगवान के पास भेजा। जो बातें आपको चोट पहुँचाती हैं, उनके साथ आप क्या करते हैं?",
 "c9f1520c": "जन्म से पहले प्रह्लाद के गुरु",
 "db101e21": "जब असुरों का राजा {hiranyakashipu|हिरण्यकशिपु} कठोर तपस्या करने मंदर पर्वत पर गया — ऐसा वरदान पाने के लिए जिससे उसे मारना लगभग असंभव हो जाए — तो देवताओं ने मौका देखा। हिरण्यकशिपु की गैरमौजूदगी में उन्होंने असुरों की नगरी पर हमला कर दिया। असुर भाग गए, और {indra|इंद्र} ने गर्भवती असुर रानी {kayadhu|कयाधू} को पकड़ लिया और उसे घसीटकर ले जाने लगे।",
 "24b90b74": "वह डरी हुई चिड़िया की तरह चीख रही थी, तभी नारद उस रास्ते से आए। उन्होंने कहा, “इंद्र, रुको! इस स्त्री ने कोई गलती नहीं की। इसे छोड़ दो।” इंद्र ने उत्तर दिया, “इसके भीतर हिरण्यकशिपु का अंश है। मैं इसे तब तक रखूँगा जब तक बच्चा पैदा न हो जाए, और फिर उसे मार डालूँगा।” नारद ने कहा: “इसके गर्भ में जो बच्चा है, वह भगवान का महान भक्त है। तुम उसे नहीं मार सकते — और तुम्हें कोशिश भी नहीं करनी चाहिए।”",
 "e77f0948": "इंद्र ने मुनि पर भरोसा किया। उन्होंने कयाधू को छोड़ दिया, और स्वर्ग लौटने से पहले उसके भीतर के भक्त का सम्मान करते हुए आदर से उसकी परिक्रमा भी की।",
 "7302d02a": "आश्रम में शिक्षा",
 "13223efe": "नारद कयाधू को अपने आश्रम ले गए और बोले, “बेटी, जब तक तुम्हारे पति लौट न आएँ, यहीं रहो।” वह वहाँ सुरक्षित रही और प्रेम से मुनि की सेवा करती रही। और नारद हर दिन उसे सिखाते — धर्म के बारे में, शरीर और आत्मा के अंतर के बारे में, और भगवान के प्रति शुद्ध प्रेम के बारे में। यह शिक्षा उसके लिए थी, पर उससे भी ज़्यादा उस बच्चे के लिए जिसे वह गर्भ में लिए थी।",
 "5efe731e": "बरसों बाद बालक {prahlada|प्रह्लाद} ने यह बात खुद अपने सहपाठियों, पाठशाला के असुर बालकों को बताई। उसने कहा, “समय बीतने पर और फिर से महल की स्त्री बन जाने पर मेरी माँ नारद की सिखाई ज़्यादातर बातें भूल गईं। पर मैंने गर्भ में ही सब सुन लिया था, और मुनि की कृपा से मैं कभी नहीं भूला।” इसीलिए भगवान के सबसे बड़े शत्रु का बेटा जन्म के दिन से ही भगवान से प्रेम करता था।",
 "11d6a451": "यह गर्भ में सीखने वाले बच्चे की सबसे पुरानी कहानियों में से एक है। महाभारत में अभिमन्यु भी अपनी माँ सुभद्रा के गर्भ में रहते हुए ही चक्रव्यूह में घुसना सीख लेते हैं।",
 "b5efc5d8": "खंभा और नरसिंह",
 "b4fe08ab": "हिरण्यकशिपु को उसका वरदान मिल गया: उसे न मनुष्य मार सके न पशु, न दिन में न रात में, न भीतर न बाहर, न धरती पर न आकाश में, न किसी अस्त्र-शस्त्र से। वह शक्ति के नशे में चूर हो गया और उसने हर जगह विष्णु की पूजा पर रोक लगा दी। जब उसने देखा कि उसका अपना नन्हा बेटा हरि का नाम जपना नहीं छोड़ता, तो उसने उसे मारने की कोशिश की — ज़हर से, हाथियों से, साँपों से, पहाड़ से फेंककर, आग से। हर बार प्रह्लाद बच गया, फिर भी मुस्कुराता हुआ, फिर भी नाम जपता हुआ।",
 "0dadee88": "आख़िर अपनी सभा में राजा गरजा: “तू कहता है तेरा भगवान हर जगह है। क्या वह इस खंभे में है?” बालक ने कहा, “हैं।” हिरण्यकशिपु ने खंभे पर प्रहार किया — और उसमें से {narasimha|नरसिंह} प्रकट हुए, न मनुष्य न पशु, बल्कि दोनों; संध्या के समय, न दिन न रात। वे राजा को देहरी पर ले गए, न भीतर न बाहर; उसे अपनी गोद में लिटाया, न धरती न आकाश; और अपने नखों से उसका वध किया, जो कोई अस्त्र नहीं हैं। फिर केवल प्रह्लाद ही भगवान का क्रोध शांत कर सका। उसने कोई इनाम नहीं माँगा, केवल यह कि उसके पिता को क्षमा कर दिया जाए।",
 "9c64f5ab": "यह कथा किसने सुनाई?",
 "a1e32e2f": "भागवत में प्रह्लाद की पूरी कथा स्वयं नारद सुनाते हैं। {yudhishthira|युधिष्ठिर} के महान राजसूय यज्ञ में राजा शिशुपाल ने बार-बार कृष्ण का अपमान किया और मारा गया — और उसके शरीर से एक ज्योति उठकर कृष्ण में समा गई। युधिष्ठिर चकित रह गए: कृष्ण से नफ़रत करने वाला उनसे एक कैसे हो गया? नारद ने समझाया कि नफ़रत भी, अगर मन को हमेशा भगवान पर टिकाए रखे, तो उन तक पहुँचा सकती है — और यही दिखाने के लिए उन्होंने हिरण्यकशिपु और उसके बेटे की कथा सुनाई।",
 "d06bb267": "तेलुगु में यह कथा बम्मेर पोतन के तेलुगु भागवत के कारण लगभग सब कथाओं से ज़्यादा प्यारी है, जो लगभग पाँच सौ साल पहले लिखा गया। तेलुगु बच्चों की कई पीढ़ियों ने अपने दादा-दादी से प्रह्लाद के पद्य कंठस्थ किए हैं।",
 "af340dc1": "प्रह्लाद और शुक्राचार्य",
 "45353aa4": "नारद ने {kayadhu|कयाधू} को इंद्र से बचाया और अपने आश्रम में शरण दी।",
 "e79778a9": "{prahlada|प्रह्लाद} ने गर्भ में नारद की शिक्षा सुनी और उसे कभी नहीं भूले।",
 "7e091e1c": "भागवत में नारद स्वयं युधिष्ठिर को प्रह्लाद की कथा सुनाते हैं।",
 "e877af96": "प्रह्लाद ने जन्म से पहले ही सीख लिया था। आपने अपने परिवार से ऐसा क्या सीखा है जो किसी ने आपको सीधे-सीधे कभी नहीं सिखाया?",
 "7bf41221": "नारद और कृष्ण",
 "b071248e": "जब भगवान {krishna|श्रीकृष्ण} के रूप में धरती पर आए, तो नारद शुरू से ही वहाँ थे — और कथा में उनकी पहली भूमिका कठिन है। {devaki|देवकी} के विवाह के समय आकाशवाणी ने उनके चचेरे भाई {kamsa|कंस} से कहा था, “इसकी आठवीं संतान तुम्हें मारेगी।” कंस उन्हें तुरंत मार डालना चाहता था, पर उनके पति वसुदेव ने वचन दिया कि वे उनसे जन्मी हर संतान उसे सौंप देंगे, और कंस ने उन्हें जीने दिया। जब पहला बेटा हुआ, तो वसुदेव ने अपना वचन निभाया और बच्चे को उसके पास ले आए। उनकी ईमानदारी से पिघलकर कंस ने बच्चा लौटा दिया: “मुझे डर तो केवल आठवें से है।”",
 "cd1b3d04": "तब नारद कंस के पास आए। उन्होंने उसे बताया कि यादव, यानी वसुदेव के लोग, असल में धरती पर जन्मे देवता हैं, और विष्णु उसका नाश करने आ रहे हैं। भागवत कहता है कि इसके बाद कंस ने वसुदेव और देवकी को कारागार में डाल दिया और उनके हर बेटे को जन्म लेते ही मार डाला। हम इसे सीधे-सीधे बताते हैं: नारद की बातों से यह सब शुरू हुआ। पुराने टीकाकार समझाते हैं कि नारद भगवान के आगमन और कंस की क्रूरता के अंत को जल्दी लाना चाहते थे; फिर भी यह कृष्ण की कथा के सबसे दुखद हिस्सों में से एक है।",
 "60f585a9": "जुड़वाँ पेड़",
 "c494e037": "धन के देवता {kubera|कुबेर} के दो बेटे थे, {nalakuvara|नलकूबर और मणिग्रीव}। घमंड और नशे में चूर होकर वे स्वर्ग की मंदाकिनी नदी में युवतियों के साथ बिना कपड़ों के खेल रहे थे। नारद संयोग से उधर से गुज़रे। स्त्रियों ने शर्माकर झट से अपने को ढक लिया; दोनों युवकों ने परवाह तक नहीं की। नारद ने देखा कि धन ने उन्हें अंधा कर दिया है।",
 "7a6a4753": "उन्होंने कहा, “तुम यहाँ पेड़ों की तरह बेशर्म खड़े हो। तो पेड़ ही बन जाओ। देवताओं के सौ वर्षों तक गोकुल में अर्जुन के दो पेड़ बनकर खड़े रहो। पर क्योंकि तुम एक भक्त के बेटे हो, तुम्हारी स्मृति बनी रहेगी, और अंत में स्वयं भगवान तुम्हें मुक्त करेंगे।” वह श्राप एक तरह की दवा था।",
 "ea49db82": "क्योंकि कृष्ण को पेट (उदर) के चारों ओर रस्सी (दाम) से बाँधा गया था, इसलिए उन्हें दामोदर कहते हैं।",
 "7897973e": "सोलह हज़ार घर",
 "3915adf5": "बाद में, जब कृष्ण अपनी बहुत-सी रानियों के साथ द्वारका में राज कर रहे थे, तब नारद को जिज्ञासा हुई। उन्होंने सोचा, “एक ही व्यक्ति इतनी सारी पत्नियों का पति कैसे हो सकता है?” वे देखने गए। वे एक महल में गए तो पाया कि कृष्ण {rukmini|रुक्मिणी} के साथ बैठे हैं, जो उन्हें पंखा झल रही थीं। कृष्ण उठे, नारद के पैर धोए और पूछा कि वे उनकी क्या सेवा कर सकते हैं।",
 "d037fb48": "नारद अगले महल में गए। वहाँ भी कृष्ण थे — एक रानी के साथ चौसर खेलते हुए। अगले में वे स्नान कर रहे थे; किसी में ब्राह्मणों को भोजन करा रहे थे; किसी में अपने बच्चों के साथ खेल रहे थे; किसी में मंत्रियों से मिल रहे थे; किसी में अकेले ध्यान में बैठे थे। हर महल में कृष्ण पूरी तरह मौजूद थे, और हर महल में उन्होंने नारद का ऐसे स्वागत किया मानो पहली बार मिल रहे हों। नारद आश्चर्य से हँस पड़े और प्रणाम करके बोले: “प्रभु, मैंने आपकी योगमाया देख ली। मुझे लोकों में घूमकर इसका गुणगान करने दीजिए।”",
 "6e15b9bf": "पारिजात का फूल",
 "f4665b1e": "हरिवंश नारद की एक और कथा बताता है जिसे तेलुगु लोग अच्छी तरह जानते हैं। नारद कृष्ण के लिए पारिजात का एक फूल लाए, जो इंद्र के स्वर्ग का मनोकामना पूरी करने वाला वृक्ष है। कृष्ण ने वह फूल रुक्मिणी को दे दिया। जब {satyabhama|सत्यभामा} ने यह सुना, तो उन्हें इतना बुरा लगा कि वे गुस्से में कोपभवन में जा बैठीं। उन्हें मनाने के लिए कृष्ण उनके साथ स्वर्ग गए और पूरा पारिजात वृक्ष ही द्वारका ले आए — उसके लिए इंद्र से युद्ध तक किया।",
 "58383d78": "तेलुगु कवि नंदि तिम्मन ने लगभग पाँच सौ साल पहले इसे प्रसिद्ध काव्य पारिजातापहरणमु में ढाला। बाद के तेलुगु नाटकों और यक्षगानों ने इसमें सत्यभामा के तुलाभारम की कहानी जोड़ दी — नारद उन्हें छेड़-छेड़कर इस बात पर उकसाते हैं कि वे कृष्ण को तराज़ू के एक पलड़े पर रखकर दूसरे पर अपना सोना तौलें, और आख़िर में केवल रुक्मिणी का एक तुलसी-पत्र ही उन्हें बराबर तौल पाता है। तुलाभारम वाली यह कहानी बाद की कथा है, जो हरिवंश या भागवत में नहीं मिलती, पर इससे पता चलता है कि तेलुगु घर नारद को कैसे याद करते हैं: ऐसे शरारती के रूप में जिसकी शरारत प्रेम सिखाती है।",
 "a7115c5a": "भागवत पुराण, स्कंध 10, अध्याय 1 (नारद और कंस), अध्याय 10 (नलकूबर और मणिग्रीव), अध्याय 9–10 (दामोदर), अध्याय 69 (नारद महलों में जाते हैं)। हरिवंश, विष्णु पर्व (पारिजात)। नंदि तिम्मन, पारिजातापहरणमु। तुलाभारम बाद की तेलुगु रंगमंच कथा है।",
 "c290d5f3": "नारद की {kamsa|कंस} को दी गई चेतावनी के कारण देवकी और वसुदेव को कारागार हुआ।",
 "901f0a08": "उन्होंने कुबेर के घमंडी बेटों को पेड़ बनने का श्राप दिया — और बालक कृष्ण ने उन्हें मुक्त किया।",
 "23f57f74": "उन्होंने कृष्ण को एक साथ उनके हर महल में पूरी तरह रहते देखा।",
 "356c644f": "कुबेर के बेटों पर नारद का श्राप वरदान निकला। क्या कभी कोई ऐसी चीज़ जो सज़ा जैसी लगी, बाद में आपके काम आई है?",
 "6bd3241a": "अभिमान और बंदर का मुँह",
 "c7500110": "नारद पूर्ण नहीं थे, और पुराने ग्रंथ ऐसा होने का दिखावा भी नहीं करते। शिव पुराण अपनी रुद्र संहिता की बिल्कुल शुरुआत में बताता है कि वे भी एक बार अभिमान में कैसे पड़ गए। वे हिमालय में गंगा के किनारे एक सुंदर गुफा में जाकर गहरे ध्यान में बैठ गए। {indra|इंद्र} ने, हमेशा की तरह इस डर से कि कोई बड़ा तपस्वी उनका सिंहासन न छीन ले, उनकी तपस्या भंग करने के लिए कामना के देवता {kama|कामदेव} को वसंत और अप्सराओं के साथ भेजा।",
 "d645fafa": "कुछ भी काम नहीं आया। कामदेव ने हर चाल आज़माई और हार गए, क्योंकि — पुराण समझाता है — उस जगह को {shiva|शिव} ने बहुत पहले आशीर्वाद दिया था, और वहाँ कोई कामना घुस नहीं सकती थी। पर नारद यह नहीं जानते थे। जब उन्होंने आँखें खोलीं और कामदेव को हारकर प्रणाम करते देखा, तो सोचा, “मैंने स्वयं काम को जीत लिया है!” और भीतर ही भीतर एक अभिमान बढ़ने लगा।",
 "e4d4d648": "वे ब्रह्मा के पास गए और डींग मारी। फिर शिव के पास गए और डींग मारी। शिव ने प्यार से सुना और कहा, “नारद, तुमने मुझे बता दिया — कोई बात नहीं। पर यह बात विष्णु को मत बताना। इसे अपने तक ही रखना।” नारद को यह सलाह अच्छी नहीं लगी। वे सीधे वैकुंठ गए और {vishnu|विष्णु} को सब कुछ बता दिया।",
 "3b574838": "राजकुमारी का स्वयंवर",
 "ad1e11f6": "विष्णु मुस्कुराए और उनकी प्रशंसा की — और अपने मित्र को अभिमान से बचाने का निश्चय किया। जाते हुए नारद को एक सुंदर नगर मिला जो पहले कभी वहाँ नहीं था, विष्णु की माया से बना हुआ। उसके राजा शीलनिधि अपनी बेटी का स्वयंवर कर रहे थे, और राजकुमारी इतनी सुंदर थी कि उसे देखते ही नारद अपनी सारी तपस्या भूल गए। वे उससे विवाह करना चाहते थे।",
 "b16b9b23": "उन्होंने सोचा, “पर वह मुझ जैसे दुबले-पतले बूढ़े तपस्वी को कैसे चुनेगी?” वे दौड़कर विष्णु के पास लौटे। “प्रभु, मुझे अपनी सुंदरता दे दीजिए — मुझे हरि का रूप दे दीजिए!” विष्णु ने कहा, “जो तुम्हारे लिए सबसे अच्छा होगा, वही करूँगा।” और उन्होंने नारद को हरि का मुख दे दिया — पर हरि शब्द का अर्थ बंदर भी होता है। नारद, यह न जानते हुए, बंदर का मुँह लिए जल्दी से स्वयंवर में पहुँच गए, यह पक्का मानकर कि वहाँ वे ही सबसे सुंदर पुरुष हैं।",
 "31e7cad5": "शिव के दो गण वेश बदलकर उनके पास बैठे और खी-खी करके हँसते रहे। राजकुमारी नारद की ओर देखे बिना आगे निकल गई — और उसने वरमाला स्वयं विष्णु के गले में डाल दी, जो एक राजा के रूप में आए थे, और वे उसे ले गए। गण हँसे: “ज़रा पानी में तो देखिए, महामुनि!” नारद ने देखा, तो एक बंदर उन्हें घूर रहा था।",
 "8d8ce5c1": "नारद का विष्णु को श्राप",
 "de981abe": "नारद क्रोध से भड़क उठे। उन्होंने दोनों गणों को राक्षस बनकर जन्म लेने का श्राप दिया। फिर वे विष्णु के पीछे दौड़े और उन्हें भी श्राप दिया: “तुमने मुझे बंदर का मुँह देकर छला। जिस स्त्री को मैं चाहता था, उसे तुम ले गए। इसलिए मनुष्य बनकर जन्म लो, और पत्नी के बिछड़ने का दुःख सहो — और बंदर ही तुम्हारी सहायता करें!” विष्णु ने मुस्कुराकर श्राप स्वीकार कर लिया। फिर उन्होंने अपनी माया हटा ली। नगर गायब हो गया; राजकुमारी चली गई; उनके पास लक्ष्मी खड़ी थीं।",
 "7017ec02": "नारद को होश आया और वे लज्जा से भर गए। वे विष्णु के चरणों में गिर पड़े: “प्रभु, यह मैंने क्या कर दिया? मैंने आपको ही श्राप दे दिया! मेरे शब्द वापस ले लीजिए।” विष्णु ने कोमलता से कहा: “नारद, तुम्हारा अभिमान दूर करना मेरी ही इच्छा थी। तुम्हारा श्राप पूरा होगा, और वह संसार के भले के लिए होगा।” शिव पुराण में वे नारद से शिव का नाम जपकर शांति पाने को कहते हैं; तुलसीदास के रामचरितमानस में यह श्राप उन कारणों में से एक बन जाता है जिनसे विष्णु {rama|राम} के रूप में जन्म लेते हैं, सीता को खोते हैं, और वानर उनकी सहायता करते हैं।",
 "6ff34ca9": "ध्यान दीजिए कि श्राप कैसे सच होता है: राम, एक मनुष्य, सीता को खो देते हैं, और हनुमान, सुग्रीव और वानर सेना ही उन्हें वापस लाने में उनकी मदद करते हैं।",
 "73fd4c32": "देवी भागवत में नारद और माया की एक और कथा है। एक बार नारद ने विष्णु से पूछा, “आप जिस माया की बात करते हैं, वह क्या है? मुझे दिखाइए।” दोनों साथ-साथ चलते हुए एक सुंदर सरोवर तक पहुँचे। विष्णु ने कहा, “यहाँ स्नान करो।” नारद पानी में उतरे — और एक सुंदर युवती बनकर बाहर निकले। उन्हें बिलकुल याद नहीं रहा कि वे पहले कौन थे।",
 "29bb4472": "तालध्वज नाम के एक राजा ने उसे देखा, उससे प्रेम हो गया और उन्होंने उससे विवाह कर लिया। वह बरसों तक उनकी रानी बनकर रही और उसके कई बेटे हुए, जो बड़े हुए और उनके भी बेटे हुए। फिर एक बड़ा युद्ध हुआ, और उसके सारे बेटे और पोते मारे गए। वह उनके शवों के पास बैठकर रोने लगी, दुख से टूट चुकी थी। तब एक बूढ़े ब्राह्मण — जो वेश बदले हुए विष्णु ही थे — आए और बोले, “क्यों रोती हो? ये किसके बेटे थे? जाओ, उस सरोवर में स्नान करो।” वह पानी में उतरी और फिर से नारद बनकर बाहर निकली, हाथ में वीणा लिए, और पास में विष्णु खड़े मुस्कुरा रहे थे। सारे सुख-दुख के साथ एक पूरा जीवन एक पल में बीत गया था।",
 "082fa172": "बाद की एक लोकप्रिय कथा इसे और सरल ढंग से कहती है: विष्णु नारद से एक लोटा पानी लाने को कहते हैं; नारद गाँव के कुएँ पर एक लड़की से मिलते हैं, उससे विवाह करते हैं, बरसों तक परिवार पालते हैं — और जब बाढ़ सबको बहा ले जाती है, तो वे खुद को फिर विष्णु के पास पाते हैं, हाथ में खाली लोटा लिए। विष्णु पूछते हैं, “मेरा पानी कहाँ है?”",
 "e8ad7557": "शिव पुराण, रुद्र संहिता, सृष्टि खंड, अध्याय 2–4 (नारद का अहंकार, स्वयंवर और श्राप)। तुलसीदास, रामचरितमानस, बालकांड (राम के जन्म के एक कारण के रूप में यह श्राप)। देवी भागवत पुराण, स्कंध 6 (नारद का स्त्री बनना)। लोटे भर पानी वाली कथा बाद में प्रचलित हुई।",
 "5a5c134f": "कामदेव को हराकर नारद को घमंड हो गया — पर असल में उनकी रक्षा उस स्थान ने की थी, जिसे शिव का आशीर्वाद मिला था।",
 "27a8377b": "हरि का रूप माँगा तो उन्हें बंदर का मुँह मिला, और गुस्से में उन्होंने {vishnu|विष्णु} को श्राप दे दिया।",
 "34c23b8f": "देवी भागवत में वे माया के एक ही पल में स्त्री बनकर पूरा जीवन जी लेते हैं।",
 "2f630123": "शिव ने नारद से कहा था, “विष्णु को मत बताना।” तुम्हें क्या लगता है, अपनी विनम्रता या इच्छाओं से मुक्त होने की डींग मारना अपने आप में एक जाल क्यों है?",
 "fcef9c2c": "नारद और पर्वत — सुकुमारी और सोने का बालक",
 "89d49068": "क्या नारद ने कभी विवाह किया? महाभारत कहता है हाँ, और यह कथा दो बार सुनाता है — एक बार द्रोण पर्व में और एक बार शांति पर्व में, जहाँ शोक में डूबे {yudhishthira|युधिष्ठिर} को {krishna|श्रीकृष्ण} यह कथा सुनाते हैं। नारद अपने भांजे, ऋषि {parvata|पर्वत} के साथ घूमा करते थे। दोनों ने आपस में एक वचन दिया था: “हमारे मन में जो भी आए, अच्छा या बुरा, हम एक-दूसरे को बताएँगे। जो यह वचन तोड़े, उस पर दूसरे का श्राप पड़े।”",
 "afef7bfa": "एक बार वे वर्षा ऋतु में राजा सृंजय के यहाँ ठहरे, जिन्होंने बड़े प्रेम से उनकी देखभाल की। उन्होंने अपनी छोटी बेटी {sukumari|सुकुमारी} को दोनों ऋषियों की सेवा का काम सौंपा। उसका कोमल स्वभाव देखकर नारद को उससे प्रेम हो गया। पर उन्होंने इस बारे में पर्वत से कुछ नहीं कहा।",
 "2824a9f5": "पर्वत को पता चल गया, और वे बहुत क्रोधित हुए कि मामा ने उनसे यह बात छिपाई। उन्होंने कहा, “आपने हमारा वचन तोड़ा है। इसलिए मेरा श्राप सुनिए: वह आपकी पत्नी बनेगी, पर जिस दिन आप उससे विवाह करेंगे, उसी दिन से उसे आपका चेहरा बंदर का दिखाई देगा।” नारद ने भी पलटकर श्राप दिया: “और तुम इस क्रोध के कारण स्वर्ग नहीं जा पाओगे!” दोनों मित्र गुस्से में अलग हो गए।",
 "43669cea": "नारद ने सुकुमारी का हाथ माँगा, और सृंजय ने उसका विवाह उनसे कर दिया। विवाह के दिन उसने अपने पति की ओर देखा तो उसे बंदर का चेहरा दिखाई दिया। फिर भी उसने मुँह नहीं फेरा। वह पहले जैसे ही प्रेम और आदर से उनकी सेवा करती रही, और उनकी पत्नी बनकर खुशी से रही।",
 "4cea128f": "कुछ समय बाद पर्वत लज्जित होकर लौटे। उन्होंने कहा, “मामा, मुझसे गलती हुई। आप मेरा श्राप हटा दीजिए, मैं आपका श्राप हटा देता हूँ।” दोनों ने एक-दूसरे को क्षमा कर दिया, और श्राप समाप्त हो गए। जब सुकुमारी ने फिर नारद को देखा, तो उसे उनका असली चेहरा दिखा, किसी देवता की तरह चमकता हुआ — और वह इतनी चौंक गई कि यह सोचकर भाग गई कि कोई अजनबी आ गया है! पर्वत ने हँसकर उससे कहा, “यह तो तुम्हारे अपने पति हैं।”",
 "6fbaafdc": "हमारी कथाओं में नारद को दो बार बंदर का मुँह मिलता है — एक बार शिव पुराण में विष्णु से, और एक बार महाभारत में पर्वत से। दोनों बार यह दुल्हन पाने की इच्छा से होता है, और दोनों बार उनका घमंड टूटता है।",
 "552ed586": "सोने का बालक",
 "f864063f": "सृंजय का कोई बेटा नहीं था, और उन्होंने ऋषियों से पुत्र माँगा। नारद ने आशीर्वाद दिया, और एक बालक पैदा हुआ जिसके शरीर से सोना निकलता था — इसलिए उसका नाम {suvarnashthivin|सुवर्णष्ठीवी} रखा गया, यानी “सोना थूकने वाला”। राजा का खज़ाना भर गया। पर सोना लालच को खींचता है। शांति पर्व के अनुसार, डाकू बच्चे को उठाकर जंगल में ले गए, सोने की तलाश में उसका शरीर चीर डाला, कुछ नहीं मिला, और उसे मरा छोड़ गए। द्रोण पर्व की कथा में इंद्र, इस डर से कि बालक आगे चलकर क्या बन जाएगा, अपना वज्र बाघ के रूप में भेजकर उसे मरवा देते हैं।",
 "0f85c898": "सृंजय दुख से टूट गए। तब नारद आकर उनके पास बैठे, और उन्हें पुराने समय के सोलह महान राजाओं की कथाएँ सुनाईं — मरुत्त, भगीरथ, राम, ययाति, शिबि, पृथु और दूसरे — हर एक सृंजय से बड़ा, उनसे ज़्यादा उदार, उनसे ज़्यादा प्रिय, और हर एक की मृत्यु हुई। नारद ने कहा, “जब उन्हें भी जाना पड़ा, तो एक ऐसे बच्चे के लिए इतना शोक मत करो जिसने कोई बड़ा काम नहीं किया था।” इस कथा को षोडश-राजिक, यानी सोलह राजाओं की कथा कहते हैं।",
 "9182aed7": "और फिर नारद ने बालक लौटा दिया: उन्होंने सुवर्णष्ठीवी को फिर से जीवित कर दिया, और राजकुमार बड़ा होकर अच्छी तरह राज करने लगा। बहुत बाद में, महाभारत में व्यास और कृष्ण यह पूरी कथा युधिष्ठिर को सुनाते हैं — पहले जब उनका भतीजा अभिमन्यु मारा जाता है, और फिर युद्ध के बाद — ताकि वे इतने लोगों की मृत्यु का दुख सह सकें।",
 "e7d966c2": "मरुत्त का सोने का यज्ञ — सोलह राजाओं में से एक",
 "fa59c507": "महाभारत, द्रोण पर्व (अभिमन्युवध पर्व: सृंजय, सुवर्णष्ठीवी और षोडश-राजिक); शांति पर्व, राजधर्म प्रकरण (कृष्ण युधिष्ठिर को नारद, पर्वत और सुकुमारी की तथा सुवर्णष्ठीवी की कथा सुनाते हैं)। बालक की मृत्यु कैसे हुई, इस पर दोनों कथाएँ अलग-अलग बातें कहती हैं।",
 "3b11a372": "नारद ने राजा सृंजय की बेटी {sukumari|सुकुमारी} से विवाह किया।",
 "31d1deb1": "{parvata|पर्वत} के श्राप से उसे वे बंदर के मुँह वाले दिखते थे — फिर भी उसने उनसे प्रेम किया।",
 "e08303b0": "नारद ने सोलह राजाओं की कथा सुनाकर सृंजय को सांत्वना दी और उनके सोने वाले बेटे को फिर से जीवित किया।",
 "e69d050c": "जब पति का चेहरा उसे अजीब दिखता था, तब भी सुकुमारी उनसे प्रेम करती रही। तुम्हें क्या लगता है, वह उसकी जगह क्या देख रही थी?",
 "af6c18ae": "पांडवों के सलाहकार",
 "697406a3": "महाभारत में नारद पांडवों के जीवन के हर बड़े मोड़ पर दिखाई देते हैं। पहली बार वे तब आते हैं जब पाँचों भाइयों का {draupadi|द्रौपदी} से विवाह हुआ ही था। नारद इंद्रप्रस्थ में उनसे मिलने आए, और उन्हें चिंता थी: पाँच भाई, एक पत्नी — अगर ईर्ष्या ने उन्हें अलग कर दिया तो? इसलिए उन्होंने उन्हें एक कथा सुनाई।",
 "f65c4ce2": "उन्होंने कहा, “एक समय {sundopasunda|सुंद और उपसुंद} नाम के दो असुर भाई थे। वे सब कुछ साथ करते थे, एक ही थाली में खाते थे, कभी एक-दूसरे से कड़वी बात नहीं कहते थे। तपस्या करके उन्होंने वरदान पाया कि उनके सिवा कोई उन्हें नहीं मार सकेगा, और उन्होंने तीनों लोक जीत लिए। उन्हें रोकने के लिए देवताओं ने विश्वकर्मा से {tilottama|तिलोत्तमा} को बनवाया, जिसे हर सुंदर चीज़ के सबसे बारीक कण से गढ़ा गया था। जब वह दोनों भाइयों के सामने से गुज़री, तो दोनों ने उसका एक-एक हाथ पकड़ लिया और कहा, ‘यह मेरी है।’ वे आपस में लड़ पड़े — और एक-दूसरे को मार डाला।”",
 "3eeb70cc": "पांडव बात समझ गए। उन्होंने नारद के सामने एक नियम बनाया: द्रौपदी बारी-बारी से हर भाई के साथ रहेगी, और अगर कोई भाई तब भीतर आ जाए जब वह किसी दूसरे भाई के साथ अकेली हो, तो उसे बारह वर्ष के लिए वन जाना होगा। कुछ ही समय बाद {arjuna|अर्जुन} को अपने अस्त्र लाने और एक ब्राह्मण की गायें बचाने के लिए यह नियम तोड़ना पड़ा — और इसलिए वे लंबी यात्रा पर निकल गए, जिसमें उन्होंने उलूपी, चित्रांगदा और सुभद्रा से विवाह किया।",
 "cf544cd3": "“कच्चित्?” — “मुझे आशा है…”",
 "f96facd6": "जब {yudhishthira|युधिष्ठिर} मय दानव की बनाई अपनी अद्भुत नई सभा में बैठे, तब नारद फिर आए। उनकी प्रशंसा करने के बजाय नारद ने उनसे एक के बाद एक सवाल पूछे, हर सवाल “कच्चित्” शब्द से शुरू होता था — “मुझे आशा है…?” “मुझे आशा है तुम अपने सैनिकों को समय पर वेतन देते हो? मुझे आशा है तुम बहुत ज़्यादा नहीं सोते और देर से नहीं उठते? मुझे आशा है तुम्हारे मंत्री ईमानदार हैं और तुम हर फ़ैसला अकेले नहीं करते? मुझे आशा है तुम्हारे राज्य के किसान केवल बारिश पर निर्भर नहीं रहते, और तुम पानी के लिए तालाब बनवाते हो? मुझे आशा है तुम अंधों, बहरों, लंगड़ों और बेसहारा लोगों की देखभाल करते हो?”",
 "8f4fec4e": "सभा पर्व की शुरुआत में आने वाला यह अध्याय दुनिया में कहीं भी अच्छे शासन की सबसे पुरानी सीखों में से एक है। फिर नारद ने इंद्र, यम, वरुण, कुबेर और ब्रह्मा की सभाओं का वर्णन किया, और युधिष्ठिर को बताया कि उनके पिता पांडु ने पितृलोक से संदेश भेजा है: राजसूय यज्ञ करो। उसी यज्ञ से जुए का खेल हुआ, और जुए के खेल से युद्ध।",
 "d59b5e46": "सावित्री, कर्ण और गालव",
 "7b73a428": "वनवास के वर्षों में ऋषि मार्कंडेय ने पांडवों को {savitri|सावित्री} की कथा सुनाई — और उसमें नारद भी हैं। जब राजकुमारी घर लौटी और बोली कि उसने {satyavan|सत्यवान} को चुना है — जो एक अंधे, राज्य से निकाले गए राजा का वन में रहने वाला बेटा था — तब नारद उसके पिता के दरबार में थे। नारद ने कहा, “वह अच्छा, सच्चा और वीर है, पर उसमें एक दोष है: आज से एक वर्ष बाद उसकी मृत्यु हो जाएगी।” पिता ने उससे दूसरा वर चुनने की विनती की। सावित्री ने कहा: “कन्या एक ही बार वर चुनती है।” नारद ने विवाह को आशीर्वाद दिया। एक वर्ष बाद सावित्री स्वयं यमराज के पीछे-पीछे गई और अपने पति को वापस ले आई।",
 "0e61be18": "युद्ध से पहले नारद ने दुर्योधन को गालव की कथा सुनाकर ज़िद न करने की चेतावनी दी। और युद्ध के बाद, जब युधिष्ठिर को पता चला कि {karna|कर्ण}, जिसे उन्होंने मारा था, उनका अपना सबसे बड़ा भाई था, तब नारद ही उनके पास बैठे और उन्हें कर्ण का पूरा दुख भरा जीवन सुनाया: कैसे एक ब्राह्मण ने उसे श्राप दिया कि युद्ध में उसके रथ का पहिया धरती में धँस जाएगा, और कैसे उसके गुरु परशुराम ने श्राप दिया कि जब उसे अपने सबसे बड़े अस्त्र की सबसे ज़्यादा ज़रूरत होगी, तब वह उसे भूल जाएगा।",
 "fc41653f": "गालव के आठ सौ घोड़े — नारद ने दुर्योधन को सुनाई कथा",
 "4355260f": "सबसे दुखद समाचार",
 "3687e174": "युद्ध के बरसों बाद {dhritarashtra|धृतराष्ट्र}, {gandhari|गांधारी} और {kunti|कुंती} वन में रहने चले गए। एक दिन नारद युधिष्ठिर के पास एक भयानक समाचार लेकर आए: जंगल में आग फैल गई थी, और वे तीनों बुज़ुर्ग शांति से योग में बैठे रहे और आग ने उन्हें अपने में ले लिया। नारद ने यह भी बताया कि वे उत्तम लोकों में गए हैं, और वह आग कोई साधारण आग नहीं थी, बल्कि उनकी अपनी पवित्र अग्नि थी, इसलिए उन्हें बहुत शोक नहीं करना चाहिए।",
 "0491f9fe": "और कृष्ण के अपने कुल के अंत के समय भी नारद मौजूद थे। मौसल पर्व बताता है कि विश्वामित्र, कण्व और नारद द्वारका आए। कुछ घमंडी यादव युवकों ने कृष्ण के बेटे सांब को गर्भवती स्त्री के कपड़े पहनाए और ऋषियों का मज़ाक उड़ाते हुए पूछा, “यह किसे जन्म देगी?” ऋषियों ने उत्तर दिया: “एक लोहे का मूसल, जो तुम्हारे पूरे वंश का नाश करेगा।” सांब ने एक मूसल को जन्म दिया; उसे पीसकर चूरा बना दिया गया और समुद्र में फेंक दिया गया, पर उससे सरकंडे उग आए, और उन्हीं सरकंडों से यादवों ने एक-दूसरे को मार डाला। भागवत भी यही कथा कहता है, ऋषियों की और लंबी सूची के साथ।",
 "d453429f": "महाभारत, आदि पर्व (सुंद और उपसुंद; पांडवों का नियम); सभा पर्व, लोकपाल-सभाख्यान (कच्चित् वाले प्रश्न और देवताओं की सभाएँ); वन पर्व, पतिव्रता-माहात्म्य (सावित्री); उद्योग पर्व (गालव); शांति पर्व, आरंभ के अध्याय (कर्ण के श्राप); आश्रमवासिक पर्व (वन की आग); मौसल पर्व (यादवों पर श्राप)। भागवत पुराण 11.1।",
 "933c54a4": "नारद की सुंद और उपसुंद वाली कथा से पांडवों ने {draupadi|द्रौपदी} के बारे में अपना नियम बनाया।",
 "bed46d78": "युधिष्ठिर से पूछे गए उनके “कच्चित्” वाले प्रश्न अच्छे शासन की एक प्रसिद्ध सीख हैं।",
 "6f0d87cf": "उन्होंने सत्यवान की मृत्यु की भविष्यवाणी की, {karna|कर्ण} की कथा सुनाई, और वे उन ऋषियों में थे जिन्होंने यादवों को श्राप दिया।",
 "ae84c056": "नारद ने युधिष्ठिर की प्रशंसा नहीं की; उन्होंने उनसे कठिन सवाल पूछे। कौन-सा मित्र तुम्हारी ज़्यादा मदद करता है — जो तुम्हारी तारीफ़ करे या जो तुमसे सवाल पूछे?",
 "edd619ab": "सनत्कुमार के सामने शिष्य",
 "7e00d48a": "अब तक हमने जो कुछ सुना, उसमें नारद एक गुरु के रूप में दिखते हैं। पर उनके बारे में सबसे पुरानी कथा, छांदोग्य उपनिषद में, उन्हें एक शिष्य के रूप में दिखाती है — और वह भी एक दुखी शिष्य। वे सदा बालक रहने वाले ऋषि {sanatkumara|सनत्कुमार} के पास गए और बोले, “भगवन्, मुझे उपदेश दीजिए।” सनत्कुमार ने कहा, “पहले मुझे बताओ कि तुम क्या-क्या जानते हो, फिर मैं तुम्हें उसके आगे की बात सिखाऊँगा।”",
 "4c9ef5b5": "नारद ने सब गिना दिया: “मैं ऋग्वेद, यजुर्वेद, सामवेद और अथर्ववेद जानता हूँ; इतिहास और पुराण, जो पाँचवाँ वेद हैं; व्याकरण, पितरों के कर्मकांड, गणित, शकुन-विद्या, काल की गणना, तर्कशास्त्र, नीति, देवताओं की विद्या, वेद की विद्या, भूत-प्रेतों की विद्या, अस्त्र-विद्या, नक्षत्र-विद्या, सर्प-विद्या, और ललित कलाएँ। भगवन्, यह सब मैं जानता हूँ।”",
 "20d4c08c": "और फिर उन्होंने सबसे सच्ची बात कही: “पर भगवन्, मैं केवल शब्दों को जानने वाला हूँ, आत्मा को जानने वाला नहीं। मैंने आप जैसे लोगों से सुना है कि आत्मा को जानने वाला दुख के पार हो जाता है। मैं दुख से भरा हूँ। कृपया मुझे पार ले चलिए।”",
 "26e880d1": "“आत्मा को जानने वाला दुख के पार हो जाता है।” (छांदोग्य उपनिषद 7.1.3)",
 "c8744a67": "सीढ़ी",
 "65b05103": "सनत्कुमार उस सारी विद्या पर हँसे नहीं। उन्होंने कहा: “तुम जो कुछ जानते हो, वह सब केवल नाम है। नाम की उपासना करो।” फिर कदम-कदम पर वे नारद को एक सीढ़ी पर ऊपर ले गए। हर बार नारद पूछते, “क्या इससे भी बड़ा कुछ है?” और हर बार सनत्कुमार कहते, “है।” नाम से बड़ी है वाणी; वाणी से बड़ा है मन; मन से बड़ा है संकल्प; फिर चित्त, फिर ध्यान, फिर विज्ञान, फिर बल, फिर अन्न, फिर जल, फिर तेज, फिर आकाश, फिर स्मृति, फिर आशा — और आशा से बड़ा है प्राण, जीवन की साँस, जिस पर सब कुछ वैसे ही टिका है जैसे पहिये की तीलियाँ उसकी धुरी पर।",
 "77ff50d8": "पर सनत्कुमार वहीं नहीं रुके। उन्होंने और ऊपर की ओर इशारा किया — सत्य की ओर, जो समझ से आता है, समझ मनन से, मनन श्रद्धा से, श्रद्धा निष्ठा से, निष्ठा कर्म से, और कर्म आनंद से। उन्होंने कहा, “आनंद को जानने की इच्छा करो। जहाँ आनंद होता है, वहीं लोग कर्म करते हैं। आनंद के बिना कोई कर्म नहीं करता।”",
 "8643804f": "अनंत",
 "d70507a6": "“और आनंद क्या है?” तब सनत्कुमार ने वे वचन कहे जिनके लिए यह उपनिषद प्रसिद्ध है।",
 "312375c5": "“जो अनंत (भूमा) है, वही आनंद है। छोटे में कोई आनंद नहीं। अनंत ही आनंद है।” (छांदोग्य उपनिषद 7.23.1)",
 "8dca5a54": "“जहाँ कोई और कुछ नहीं देखता, और कुछ नहीं सुनता, और कुछ नहीं जानता — वह अनंत है। जहाँ कोई कुछ और देखता है, कुछ और सुनता है, कुछ और जानता है — वह छोटा है। अनंत अमर है; छोटा नश्वर है।” और यह अनंत, उन्होंने कहा, नीचे भी है और ऊपर भी, पीछे भी और आगे भी, दक्षिण में भी और उत्तर में भी — यह सब वही है। और वही आत्मा है। “जो इसे देखता है, इसका मनन करता है, इसे जानता है, वह आत्मा में ही आनंद लेता है, आत्मा में ही खेलता है, आत्मा से जुड़ा रहता है, और सभी लोकों में स्वतंत्र होता है।”",
 "ab26e668": "उपनिषद इस उपदेश को एक सुंदर पंक्ति के साथ समाप्त करता है: जिनके सारे दोष धुल चुके थे, उन नारद को भगवान सनत्कुमार ने अंधकार के पार का किनारा दिखाया। हर ग्रंथ को जानने वाले उस महान विद्वान को आख़िरकार वह एक चीज़ मिल गई जो कोई किताब उन्हें नहीं दे सकती थी।",
 "475d9e5d": "सनत्कुमार और उनके तीन भाई ब्रह्मा के मानस पुत्र हैं, जिन्होंने हमेशा के लिए पाँच साल के बालक बने रहना चुना, ताकि वे कभी संसार में न उलझें। यहाँ एक बालक ब्रह्मांड के सबसे विद्वान ऋषि को उपदेश देता है।",
 "b0927f4d": "छांदोग्य उपनिषद, अध्याय 7 (नारद और सनत्कुमार का संवाद), विशेषकर 7.1 (नारद की विद्या और उनका दुख), 7.2–7.15 (प्राण तक की सीढ़ी), 7.16–7.25 (सत्य, आनंद और भूमा) और 7.26 (अंधकार के पार का किनारा)।",
 "93763ba2": "नारद सारे वेद और शास्त्र जानते थे, फिर भी उन्होंने कहा, “मैं शब्दों को जानता हूँ, आत्मा को नहीं।”",
 "c9dcd4d3": "{sanatkumara|सनत्कुमार} उन्हें कदम-कदम पर नाम से प्राण तक, और उससे भी आगे ले गए।",
 "7d775f29": "“छोटे में कोई आनंद नहीं; अनंत ही आनंद है।”",
 "6f5f5a40": "नारद सब कुछ सीख चुके थे, फिर भी दुखी थे। क्या कोई व्यक्ति बहुत कुछ जानकर भी ज्ञानी न हो, ऐसा हो सकता है? दोनों में क्या फ़र्क है?",
 "72ced4fd": "भक्ति सूत्र — “देवर्षियों में मैं नारद हूँ”",
 "c96a714f": "चौरासी सूत्रों की एक छोटी-सी पुस्तक नारद के नाम से जानी जाती है: नारद भक्ति सूत्र। विद्वानों का मानना है कि यह उपनिषदों से बहुत बाद में संकलित हुई, पर यह भक्ति पर सबसे प्रिय पुस्तकों में से एक बन गई है। इसकी शुरुआत बहुत सरल है:",
 "496f0d4e": "“अब हम भक्ति की व्याख्या करेंगे। वह भगवान के प्रति परम प्रेम का रूप है।” (नारद भक्ति सूत्र 1–2)",
 "4203cfad": "सूत्र कहते हैं कि यह प्रेम अमृत जैसा मीठा है; जिसे यह मिल जाता है, वह पूर्ण और तृप्त हो जाता है; यह कर्मकांड, ज्ञान या योग से भी बड़ा है, क्योंकि यह स्वयं ही लक्ष्य है। और ऐसे प्रेम का सबसे ऊँचा उदाहरण वे किसी ऋषि या राजा को नहीं, बल्कि गोपियों को बताते हैं — व्रज की ग्वालिनें, जिन्होंने अपने पूरे मन-प्राण से कृष्ण से प्रेम किया।",
 "b62ceb83": "एक सूत्र कहता है कि सच्चे भक्त जब आपस में मिलते हैं, तो रुँधे गले, आँसुओं और आनंद के रोमांच के साथ भगवान की बातें करते हैं — और ऐसे लोग पवित्र तीर्थों को भी पवित्र बना देते हैं।",
 "04497521": "गीता में",
 "b1cc7cae": "भगवद्गीता में नारद का नाम दो बार आता है। दसवें अध्याय में अर्जुन आश्चर्य से कृष्ण से कहते हैं: “सभी ऋषि आपको शाश्वत, दिव्य और देवताओं में आदि कहते हैं — देवर्षि नारद भी यही कहते हैं, और असित, देवल और व्यास भी — और अब आप स्वयं मुझसे कह रहे हैं।” थोड़ा आगे, जब {krishna|श्रीकृष्ण} उन चीज़ों को गिनाते हैं जिनमें उनकी महिमा सबसे ज़्यादा चमकती है, तो वे कहते हैं:",
 "f650b5f6": "“सब वृक्षों में मैं पीपल (अश्वत्थ) हूँ; देवर्षियों में नारद; गंधर्वों में चित्ररथ; और सिद्धों में कपिल मुनि।” (भगवद्गीता 10.26)",
 "1d230603": "नारद ने हमें क्या दिया",
 "3ff1a250": "कई ग्रंथों पर नारद का नाम है। स्वयं ऋग्वेद में आठवें और नौवें मंडल के कुछ सूक्त कण्व वंश के नारद के बताए जाते हैं, उनमें से कुछ पर्वत के साथ। नारद स्मृति कानून पर सबसे सावधानी से लिखी गई पुरानी पुस्तकों में से एक है — अनुबंध, कर्ज़, गवाह और अदालतों के बारे में। एक नारद पुराण है, पूजा-विधि पर नारद पंचरात्र है, और सामवेद के गायन पर नारदीय शिक्षा है।",
 "7f2178cd": "और नारद दूसरे ऋषियों के जीवन में भी आते-जाते रहते हैं। उन्होंने विंध्य का घमंड इतना बढ़ा दिया कि अगस्त्य को दक्षिण आना पड़ा। उन्होंने राजा मरुत्त को बताया कि संवर्त कहाँ मिलेंगे। वे अंगिरा के साथ राजा चित्रकेतु को सांत्वना देने आए। उन्होंने दुर्योधन को गालव की कथा सुनाई। जहाँ भी किसी बड़ी कथा को शुरू होने के लिए एक धक्के की ज़रूरत होती है, वहाँ अक्सर नारद मुस्कुराते हुए “नारायण, नारायण” कहते मिल जाते हैं।",
 "d25d0d1b": "दूसरे ऋषियों के जीवन में नारद",
 "9ff30d6d": "अध्याय खोलने के लिए छुएँ",
 "3769cb70": "झुकने वाला पर्वत — अगस्त्य और विंध्य",
 "c79e40d6": "संवर्त और राजा मरुत्त का सोने का यज्ञ",
 "4322b06f": "राजा चित्रकेतु का पुत्र",
 "1408e5e7": "घुमक्कड़ जो सदा घर में है",
 "ff03c90d": "उनके जीवन पर फिर से नज़र डालो। एक दासी का बेटा, जिसने ऋषियों की सेवा की और उनकी बातें सुनीं। ब्रह्मा का एक पुत्र, जिसने विवाह करने से मना किया और जिसे हमेशा भटकते रहने का श्राप मिला। ध्रुव और प्रह्लाद के गुरु — दो बच्चे जिन्होंने भगवान से प्रेम किया। एक झगड़ा कराने वाले, जिनके झगड़े से क्रूरता का अंत हुआ। एक घमंडी ऋषि, जिन्हें बंदर का मुँह मिला। एक पति। राजाओं के सलाहकार। एक शिष्य, जो सब कुछ जानकर भी दुखी था, जब तक एक बालक ने उसे अनंत नहीं दिखा दिया।",
 "cd352df8": "दक्ष ने उन्हें श्राप दिया कि उनका कभी कोई घर न हो। पर नारद ने उस श्राप को कुछ और ही बना दिया: क्योंकि वे कहीं टिक नहीं सकते थे, उन्होंने भगवान के नाम को ही अपना घर बना लिया और जहाँ भी गए, उसे साथ ले गए। बहुत-से हिंदू वैशाख पूर्णिमा के अगले दिन, नारद जयंती पर उन्हें याद करते हैं। और जब भी कोई भगवान के गीत गाते हुए दुनिया भर में घूमता है — कर्नाटक के हरिदास, तेलुगु गाँवों की भजन मंडलियाँ, बंगाल के कीर्तन गायक — तो लोग कहते हैं, “वह देखो, एक नारद जा रहा है।”",
 "1ebbb0b4": "नारद भक्ति सूत्र (विशेषकर सूत्र 1–2 और व्रज की गोपियों वाले सूत्र)। भगवद्गीता 10.13 और 10.26। ऋग्वेद, मंडल 8 और 9 (नारद काण्व और पर्वत के बताए जाने वाले सूक्त)। नारद स्मृति; नारद पुराण; नारदीय शिक्षा।",
 "dfa66ed7": "नारद भक्ति सूत्र भक्ति को भगवान के प्रति परम प्रेम बताते हैं।",
 "91dee108": "गीता में {krishna|श्रीकृष्ण} कहते हैं: “देवर्षियों में मैं नारद हूँ।”",
 "4f8d9ce8": "घर न होने का श्राप मिलने पर नारद ने भगवान के नाम को ही अपना घर बना लिया।",
 "304481a3": "नारद ने दक्ष के श्राप को — कि उनका कभी घर न हो — जीने का एक ढंग बना लिया। क्या तुम्हारे जीवन में भी कोई कमी है जिसे तुम अपनी ताक़त बना सकते हो?",
 "2abe069f": "व्यास",
 "442f7aae": "कृष्ण द्वैपायन, पराशर और सत्यवती के पुत्र, जिन्होंने वेद का विभाजन किया और महाभारत की रचना की।",
 "e2b4d07a": "हर्यश्व",
 "5262ca99": "दक्ष के दस हज़ार पुत्र, जिन्हें संसार को संतानों से भरने के लिए भेजा गया था, पर जिन्होंने नारद की बातें सुनकर संन्यास ले लिया।",
 "4ffe44de": "ध्रुव",
 "0f6e3044": "राजा उत्तानपाद के पुत्र, जिन्होंने छोटी-सी उम्र में तपस्या की और ध्रुव तारा बन गए।",
 "57e66188": "उत्तानपाद",
 "1d1ba6e7": "स्वायंभुव मनु के एक पुत्र, राजा, और ध्रुव तथा उत्तम के पिता।",
 "8f7e16ef": "सुनीति",
 "f4ebc133": "उत्तानपाद की उपेक्षित बड़ी रानी, ध्रुव की माता।",
 "3dfc9f16": "सुरुचि",
 "8763a567": "उत्तानपाद की प्रिय रानी, उत्तम की माता।",
 "3ccfc2c3": "हिरण्यकशिपु",
 "7683e23e": "विष्णु से घृणा करने वाला शक्तिशाली असुर राजा, जिसने अपने ही पुत्र प्रह्लाद को सताया, जब तक नरसिंह ने उसका वध नहीं किया।",
 "3de183b7": "कयाधु",
 "1a2ea9be": "हिरण्यकशिपु की पत्नी और प्रह्लाद की माता।",
 "b1e854a2": "नरसिंह",
 "2a013c15": "नर-सिंह के रूप में विष्णु, जो प्रह्लाद की रक्षा के लिए खंभे से प्रकट हुए।",
 "ef0edc43": "कंस",
 "8a3322f6": "मथुरा का क्रूर राजा, देवकी का चचेरा भाई, जो उसके आठवें पुत्र से डरता था और जिसे कृष्ण ने मारा।",
 "03005f7b": "देवकी",
 "e2e59705": "वसुदेव की पत्नी और कृष्ण की माता, जिन्हें उनके चचेरे भाई कंस ने कैद में रखा।",
 "c4f8471f": "नलकूबर और मणिग्रीव",
 "1a57aa00": "कुबेर के दो पुत्र, जिन्हें नारद ने जुड़वाँ अर्जुन वृक्ष बनकर खड़े रहने का श्राप दिया, जब तक बाल कृष्ण ने उन्हें मुक्त नहीं किया।",
 "63be39ef": "रुक्मिणी",
 "359fe1bb": "विदर्भ की राजकुमारी और कृष्ण की प्रमुख रानी।",
 "755def88": "सत्यभामा",
 "afd3130f": "श्रीकृष्ण की प्रमुख रानियों में से एक, स्वाभिमानी और साहसी, जो तेलुगु कथाओं और नाटकों में बहुत प्रिय हैं।",
 "c1a31940": "पर्वत",
 "5a99d37f": "एक ऋषि, नारद के भांजे और उनके यात्रा के साथी।",
 "e1840448": "सृंजय",
 "58318f2c": "एक राजा, जिन्होंने नारद और पर्वत का आतिथ्य किया; सुकुमारी के और सोने के बालक सुवर्णष्ठीवी के पिता।",
 "5fcf0835": "सुकुमारी",
 "4f683401": "राजा सृंजय की बेटी, जो नारद की पत्नी बनीं।",
 "d8f1852b": "सुवर्णष्ठीवी",
 "7f3b7bac": "सृंजय का पुत्र, जो नारद के आशीर्वाद से जन्मा; उसके शरीर से सोना निकलता था, इसलिए उसका यह नाम पड़ा।",
 "1fea9dbd": "द्रौपदी",
 "67d388e5": "पांचाल की राजकुमारी, जो यज्ञ की अग्नि से जन्मी थीं और पाँचों पांडवों की पत्नी बनीं।",
 "d2b8405d": "अर्जुन",
 "1e10148d": "तीसरे पांडव, महान धनुर्धर, कृष्ण के मित्र, जिन्हें भगवद्गीता का उपदेश मिला।",
 "9d426ac6": "सुंद और उपसुंद",
 "453f0d3a": "दो असुर भाई, जो कभी अलग नहीं होते थे, पर अप्सरा तिलोत्तमा के लिए झगड़कर एक-दूसरे को मार बैठे।",
 "cfa9e6f6": "तिलोत्तमा",
 "64af290b": "एक अप्सरा, जिसे विश्वकर्मा ने हर सुंदर चीज़ के सबसे बारीक कण से गढ़ा।",
 "81221ae9": "सावित्री",
 "ab5f288f": "वह राजकुमारी जिसने यह जानते हुए भी सत्यवान को चुना कि एक वर्ष में उसकी मृत्यु हो जाएगी, और यमराज से उसे वापस ले आई।",
 "71b0887b": "सत्यवान",
 "7b2f3027": "राज्य से निकाले गए एक अंधे राजा का पुत्र, जो वन में रहता था — सावित्री के पति।",
 "5a89ec29": "कर्ण",
 "b756af1d": "कुंती का पहला पुत्र, सूर्य से जन्मा, एक सारथी के घर पला, और अपने ही भाइयों के विरुद्ध लड़ा।",
 "39bb9bea": "धृतराष्ट्र",
 "87ef75c5": "कुरु वंश के अंधे राजा, दुर्योधन और उसके निन्यानवे भाइयों के पिता।",
 "540eacb6": "गांधारी",
 "54b106f3": "धृतराष्ट्र की रानी, जिन्होंने पति के देख न पाने के कारण जीवन भर अपनी आँखों पर पट्टी बाँधे रखी।",
 "3505d2d4": "कुंती",
 "d4f5af1a": "कर्ण की और तीन बड़े पांडवों की माता।",
 "033ffa1d": "सनत्कुमार",
 "9594425a": "चार कुमारों में सबसे बड़े — ब्रह्मा के मानस पुत्र, जो सदा बालक ही रहते हैं; छांदोग्य उपनिषद में नारद के गुरु।",
 "8823c0c1": "वाल्मीकि",
 "17769f27": "एक महान ऋषि, जो तमसा नदी के किनारे एक आश्रम में रहते थे। वे आदि कवि बने और उन्होंने रामायण की रचना की।",
});
